<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{deleteStaticResource,listStaticResources,listStaticTrash,restoreStaticResource,uploadStaticResource,type StaticEntry,type TrashEntry}from'../../api/staticResources';const entries=ref<StaticEntry[]>([]),trash=ref<TrashEntry[]>([]),uploadPath=ref('site/'),file=ref<File|null>(null);const asEntry=(row:unknown)=>row as StaticEntry;const asTrash=(row:unknown)=>row as TrashEntry;onMounted(refresh);async function refresh(){[entries.value,trash.value]=await Promise.all([listStaticResources(),listStaticTrash()])}function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]??null}async function upload(){if(!file.value){ElMessage.warning('请选择文件');return}const path=uploadPath.value.endsWith('/')?uploadPath.value+file.value.name:uploadPath.value;try{await uploadStaticResource(path,file.value,false);ElMessage.success('静态资源已上传');await refresh()}catch(e){ElMessage.error(e instanceof Error?e.message:'上传失败')}}async function remove(row:StaticEntry){if(row.directory)return;try{await ElMessageBox.confirm('系统不会完整检查该资源是否正在被页面、CSS、JS 或静态页面引用。删除后将先进入回收区，是否继续？','静态资源删除风险',{type:'warning',confirmButtonText:'移入回收区'});await deleteStaticResource(row.path);await refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'删除失败')}}async function restore(row:TrashEntry){try{await restoreStaticResource(row.id);await refresh();ElMessage.success('资源已恢复')}catch(e){ElMessage.error(e instanceof Error?e.message:'恢复失败')}}</script><template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">高风险站点能力</p><h1>网站静态资源管理</h1><p class="subtitle">浏览和管理指定网站静态目录。系统不提供完整资源引用关系检查。</p></div></header><el-alert title="删除或替换静态资源可能破坏正在使用该 URL 的页面；当前系统不会完整扫描所有引用。" type="warning" :closable="false" show-icon/><el-card shadow="never" style="margin-top:16px"><div class="resource-upload"><el-input v-model="uploadPath" placeholder="例如 site/banner/"/><input type="file" @change="choose"><el-button type="primary" @click="upload">上传</el-button></div><el-table :data="entries"><el-table-column prop="path" label="路径"/><el-table-column label="类型" width="100"><template #default="s">{{s.row.directory?'目录':'文件'}}</template></el-table-column><el-table-column prop="size" label="大小" width="120"/><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="!s.row.directory" link type="danger" @click="remove(asEntry(s.row))">删除</el-button></template></el-table-column></el-table></el-card><el-card shadow="never" style="margin-top:16px"><template #header>回收区</template><el-table :data="trash"><el-table-column prop="originalPath" label="原路径"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="restore(asTrash(s.row))">恢复</el-button></template></el-table-column></el-table></el-card></main></template><style scoped>.resource-upload{display:grid;grid-template-columns:1fr 260px auto;gap:12px;margin-bottom:16px}</style>
